head.script:
// 테스트 설명, 유효성 값 설정
//  - _1 담당 : 영역별 쓰임 (Header / Body / Footer / SubTotal) + Header·Footer HTML 이스케이프
//  - _2 담당 : Body 데이터 미적용·defaultValue 상호 적용·엑셀 다운로드·편집 전환 / _3 담당 : expression 무시·checkbox/radio trueValue
scwin.tData = {
    "description" : "[column > P > value]<br/>Column 에 표시하거나 사용할 값을 설정합니다.",
    "validation" : [
        "Column 이 속한 영역과 inputType 속성값에 따라 속성값의 쓰임이 달라집니다.",
        "문자열 설정 시, Header 영역 : Header Column 에 표시할 텍스트로 사용됩니다.",
        "문자열 설정 시, Body 영역 : Body Column 값이 ''(Empty String)일때 대신 표시할 텍스트로 사용됩니다.",
        "문자열 설정 시, Footer 영역 : Footer Column 에 표시할 텍스트로 사용되며 dataType, displayFormat, displayFormatter 속성에 따라 포맷된 문자열이 표시됩니다.",
        "문자열 설정 시, SubTotal 영역 : 소계 계산 결과가 없는 SubTotal Column 에 표시할 텍스트로 사용되며 포맷은 적용되지 않습니다.",
        "Header 와 Footer 영역에 설정한 값에 HTML 태그가 포함되어 있으면 이스케이프 처리되지 않습니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (일반 텍스트)
    con_value.setSelectedIndex(1);

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// XML 속성값 인코딩 (HTML 태그가 포함된 값을 dynamicCreate 마크업 속성으로 넘기기 위함)
scwin.encodeAttr = function (str) {
    return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}



// comp 생성
//  - 비고(note) Column : Header / Body / SubTotal / Footer 4개 영역 모두에 value = con_value 적용 (dataType 미설정)
//  - 금액(amount) Column : SubTotal / Footer 영역에 value = con_value 와 dataType=number, displayFormat=#,##0 을 함께 적용 (포맷 적용 여부 대조)
//  - Body 비고 데이터 : Row 0, 2 는 ''(Empty String), Row 1, 3 은 값 보유
//  - SubTotal 은 지역(region) 기준, 소계 계산(expression) Column 없이 구성
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 비고 Column 은 Header / Body / SubTotal / Footer 모두에 value 적용, 금액 Column 은 SubTotal / Footer 에만 value 와 dataType=number, displayFormat=#,##0 적용 (SubTotal 은 소계 계산 Column 없음)\n[확인] (표시값 확인) 버튼 출력 형식\nHeader 비고 표시 텍스트 / HTML\nRow n 비고 데이터값 / 표시값\nSubTotal n 금액 표시값 / 비고 표시값\nFooter 금액 표시값 / 비고 표시 텍스트 / HTML"', '', 'label1');

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cValue = con_value.getValue();
    let attrValue = (cValue === '') ? '' : ' value="' + scwin.encodeAttr(cValue) + '"';
    let attrFormat = ' dataType="number" displayFormat="#,##0"';

    // dataList 생성 (지역별 연속 배치 : SubTotal 이 지역이 바뀌는 지점에 삽입되도록)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="region" name="지역" dataType="text"></w2:column>';
    strDlt += '<w2:column id="product" name="상품" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="금액" dataType="number"></w2:column>';
    strDlt += '<w2:column id="note" name="비고" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "region" : "서울", "product" : "노트북", "amount" : "1250000", "note" : "" },
        { "region" : "서울", "product" : "모니터", "amount" : "320000", "note" : "재고 부족" },
        { "region" : "부산", "product" : "키보드", "amount" : "89000", "note" : "" },
        { "region" : "부산", "product" : "마우스", "amount" : "45000", "note" : "입고 예정" }
    ], false);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:560px;height:340px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="column1" value="지역"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column2" value="상품"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column3" value="금액"></w2:column>';
    strTarget += '<w2:column width="190" style="" inputType="text" id="column4"' + attrValue + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="region" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="product" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="amount" value="" dataType="number" displayFormat="#,##0"></w2:column>';
    strTarget += '<w2:column width="190" style="" inputType="text" id="note"' + attrValue + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:subTotal style="" id="subTotal1" targetColumnID="region">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="sub_col1" value="소계"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="sub_col2" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="sub_col3"' + attrValue + attrFormat + '></w2:column>';
    strTarget += '<w2:column width="190" style="" inputType="text" id="sub_col4"' + attrValue + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:subTotal>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row4">';
    strTarget += '<w2:column width="90" style="" inputType="text" id="foot_col1" value="합계"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="foot_col2" value=""></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="foot_col3"' + attrValue + attrFormat + '></w2:column>';
    strTarget += '<w2:column width="190" style="" inputType="text" id="foot_col4"' + attrValue + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// Cell 의 표시 텍스트(textContent) 와 HTML(innerHTML) - 내용을 감싸는 nobr / div 가 있으면 그 내부 기준
scwin.getCellContent = function (td) {
    if (!td) {
        return { "text" : "Cell 없음", "html" : "Cell 없음" };
    }
    let inner = td.querySelector("nobr, div") || td;
    return { "text" : inner.textContent, "html" : inner.innerHTML };
}



// validation 1 ~ 6 판정 출력 : 영역별 비고 / 금액 Column 표시값 (전체 Body Row, 전체 SubTotal Row)
//  - validation 2, 6 : Header 비고 표시 텍스트 / HTML
//  - validation 3    : Row n 비고 데이터값 / 표시값 (데이터 '' Row 에 value 표시)
//  - validation 5    : SubTotal n 금액 표시값(포맷 미적용) / 비고 표시값
//  - validation 4, 6 : Footer 금액 표시값(포맷 적용) / 비고 표시 텍스트 / HTML
//  - validation 1    : 위 영역별 결과 대조
scwin.btn_checkValue_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    let gridId = target1.id;

    // Header
    let header = scwin.getCellContent(document.querySelector("#" + gridId + "_column4"));
    bottom.setReturnValue("Header '" + header.text + "' / '" + header.html + "'");

    // Body (전체 Row)
    let tbody = document.querySelector("#" + gridId + "_body_tbody");
    let bodyTds = tbody ? tbody.querySelectorAll("tr:not([data-subtotalrowindex]) td[data-col_id='note']") : [];
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        let body = scwin.getCellContent(bodyTds[i]);
        bottom.setReturnValue("Row " + i + " '" + dlt_bind.getCellData(i, "note") + "' / '" + body.text + "'");
    }

    // SubTotal (숨김 예비 Row 제외)
    let subRows = target1.render.querySelectorAll("tr[data-subtotalrowindex]");
    for (let i = 0; i < subRows.length; i++) {
        let tds = subRows[i].querySelectorAll("td");
        let subAmount = scwin.getCellContent(tds[tds.length - 2]);
        let subNote = scwin.getCellContent(tds[tds.length - 1]);
        bottom.setReturnValue("SubTotal " + i + " '" + subAmount.text + "' / '" + subNote.text + "'");
    }

    // Footer
    let footAmount = scwin.getCellContent(document.querySelector("#" + gridId + "_foot_table td[id$='foot_col3']"));
    let footNote = scwin.getCellContent(document.querySelector("#" + gridId + "_foot_table td[id$='foot_col4']"));
    bottom.setReturnValue("Footer '" + footAmount.text + "' / '" + footNote.text + "' / '" + footNote.html + "'");
}
